'use strict';

// Generates a v4 UUID using the platform's native crypto, working across
// browsers, web workers and Node.js without any external dependency.
//
// `globalThis.crypto` is the Web Crypto API. It is present in browser windows,
// web workers (both expose it as a global) and Node.js >= 19. Browserify leaves
// this global untouched - it only shims `require('crypto')` - so the browser
// bundle always reaches the native implementation here.
//
// The `require('crypto')` fallback covers Node.js 14.17 - 18, where the crypto
// module has `randomUUID` but it is not yet exposed as a global. This branch is
// never executed in the browser bundle.
function randomUUID() {
  if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.randomUUID) {
    return globalThis.crypto.randomUUID();
  }
  // eslint-disable-next-line global-require
  return require('crypto').randomUUID();
}

module.exports = randomUUID;
